import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BS0bAV7E.js";const p=JSON.parse('{"title":"Memory management","description":"","frontmatter":{},"headers":[],"relativePath":"arch/memory.md","filePath":"arch/memory.md"}'),s={name:"arch/memory.md"};function i(n,e,c,m,h,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="memory-management" tabindex="-1">Memory management <a class="header-anchor" href="#memory-management" aria-label="Permalink to &quot;Memory management&quot;">​</a></h1><h2 id="pmm-the-physical-page-store" tabindex="-1">PMM - the physical page store <a class="header-anchor" href="#pmm-the-physical-page-store" aria-label="Permalink to &quot;PMM - the physical page store&quot;">​</a></h2><p><code>kernel/mem/mem_pmm.{c,h}</code>: a bitmap over 4 KiB page frames built from the multiboot2 memory map. Reserved regions (kernel image, framebuffer, the mbi itself) are marked used at init. O(1) alloc and free. <code>memtest</code> / <code>pmmrace</code> exercise it in-guest.</p><h2 id="vmm-four-level-paging" tabindex="-1">VMM - four-level paging <a class="header-anchor" href="#vmm-four-level-paging" aria-label="Permalink to &quot;VMM - four-level paging&quot;">​</a></h2><p><code>kernel/mem/mem_vmm.{c,h}</code>: the kernel keeps boot.S&#39;s identity map of the low 4 GiB; VMM creates and edits additional address spaces for user processes. Protection flags map to read/write/nx/user bits. <code>vmtest</code>, <code>vmmap</code>, <code>vmkernelpt</code>, <code>cr3test</code> inspect it live.</p><h2 id="heap-kmalloc-kfree" tabindex="-1">Heap - kmalloc/kfree <a class="header-anchor" href="#heap-kmalloc-kfree" aria-label="Permalink to &quot;Heap - kmalloc/kfree&quot;">​</a></h2><p><code>kernel/mem/mem_heap.{c,h}</code>: free-list, first-fit, coalescing; blocks are 16-byte aligned (the header is exactly 32 bytes - a historical alternating-parity bug made payload alignment depend on allocation parity, which then shifted ATA-DMA PRDT windows and broke FAT32 mounts; the header size is now static-asserted). 16 MiB fail-fast ceiling; <code>heaptest</code> + <code>heapbounds</code> are the tests, <code>heap</code>/<code>frag</code> the inspectors.</p><h2 id="growth-by-fault" tabindex="-1">Growth by fault <a class="header-anchor" href="#growth-by-fault" aria-label="Permalink to &quot;Growth by fault&quot;">​</a></h2><p>Stack-growth and heap-growth #PF are handled in the exception path: a fault below a task&#39;s stack pointer within its stack region maps a new page; heap growth maps backing pages; anything else escalates to the crash path. <code>exc</code> proves the trap machinery each boot.</p><h2 id="dma-constraints" tabindex="-1">DMA constraints <a class="header-anchor" href="#dma-constraints" aria-label="Permalink to &quot;DMA constraints&quot;">​</a></h2><p>Drivers that program physical addresses into device structures validate alignment and, for 32-bit DMA masks, that the address is below 4 GiB (xHCI refuses above-4GiB DMA at probe AND per-transfer; ATA-DMA masks the PRDT). This is why the heap&#39;s alignment guarantees are load-bearing.</p>',11)])])}const f=a(s,[["render",i]]);export{p as __pageData,f as default};
